    await setDoc(doc(collection(db, "courses"), "HG3021"), {
    "code": "HG3021",
    "name": "LANGUAGE CHANGE",
    "description": "This course introduces students to concepts and methodologies in study of language change. Traditionally the study of language change is divided between historical linguistics (sometimes called diachronic linguistics) and comparative linguistics. Both subfields study focus on different dimensions of language change. In the diachronic dimension we seek answers to how and why languages change over time. In the synchronic dimension we classify languages into families and study situations which lead to language change. The course will cover both descriptive and theoretical components. A fair amount of time will be spent on mastering the descriptive tools to enable students to independently analyze patterns of language change. At the same time, a number of theoretical issues related to grammaticalization and language evolution will be discussed to introduce students to current debates in the field.",
    "prereq": "HG2003 & HG2034",
    "au_count": 3,
    "letter_grade": false,
    "indexes": [
        "17426"
    ]
});
